+package com.example;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.BrowserType;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
+        properties = "vaadin.launch-browser=false")
+class ContactBrowserTest {
+    @LocalServerPort
+    int port;
+
+    @Test
+    void contactWorksWithRealClientEvents() {
+        try (Playwright playwright = Playwright.create();
+             Browser browser = playwright.chromium().launch(new BrowserType.LaunchOptions()
+                     .setHeadless(true).setArgs(java.util.List.of("--no-sandbox")))) {
+            Page page = browser.newPage();
+            page.navigate("http://localhost:" + port + "/contact");
+            var send = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send").setExact(true));
+            assertThat(send).isEnabled();
+            send.click();
+            assertThat(page.getByText("Name is required", new Page.GetByTextOptions().setExact(true))).isVisible();
+            assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+            assertThat(page.getByText("Message is required", new Page.GetByTextOptions().setExact(true))).isVisible();
+            page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).fill("Browser sender");
+            page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).fill("5551234");
+            page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("Browser message");
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+            assertThat(page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true))).hasValue("Browser message");
+            page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).press("Enter");
+            assertThat(send).isDisabled();
+            assertThat(page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true))).isEmpty();
+            assertThat(page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true))).isEmpty();
+            assertThat(page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true))).isEmpty();
+            assertThat(page.locator("vaadin-notification-card")).containsText("Message sent");
+            assertThat(page.locator("vaadin-grid")).containsText("Browser sender");
+            page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("new draft");
+            assertThat(send).isEnabled();
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard").setExact(true)).click();
+            assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About").setExact(true))).isVisible();
+            page.goBack();
+            assertThat(page.locator("vaadin-grid")).containsText("Browser sender");
+        }
+    }
+}
