+import com.example.views.ContactView;
+import com.example.views.SentMessages;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    @BeforeEach
+    void openContact() {
+        navigate(ContactView.class);
+    }
+
+    private TextField name() { return find(TextField.class).withLabel("Name").single(); }
+    private TextField phone() { return find(TextField.class).withLabel("Phone").single(); }
+    private EmailField email() { return find(EmailField.class).single(); }
+    private TextArea message() { return find(TextArea.class).single(); }
+    private Button send() { return find(Button.class).withText("Send").single(); }
+    private void click(String text) { test(find(Button.class).withText(text).single()).click(); }
+    private int rows() { return find(Grid.class).single().getListDataView().getItemCount(); }
+    private SentMessages.Message first() {
+        return (SentMessages.Message) find(Grid.class).single().getListDataView().getItem(0);
+    }
+    private void fillPhoneMessage() {
+        test(name()).setValue("Ada");
+        test(phone()).setValue("12345");
+        test(message()).setValue("Hello");
+    }
+
+    @Test
+    void emptySubmissionValidatesEveryRequiredFieldWithoutSending() {
+        int count = rows();
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertTrue(send().isEnabled());
+        click("Send");
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertEquals(count, rows());
+        assertFalse(find(Notification.class).exists());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void invalidEmailAndLongMessagePreserveDraftAndCanBeCorrected() {
+        int count = rows();
+        fillPhoneMessage();
+        test(email()).setValue("invalid");
+        test(message()).setValue("x".repeat(501));
+        click("Send");
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals("Ada", name().getValue());
+        assertEquals(501, message().getValue().length());
+        assertEquals(count, rows());
+        assertFalse(find(Notification.class).exists());
+        test(email()).setValue("ada@example.com");
+        test(message()).setValue("x".repeat(500));
+        click("Send");
+        assertEquals(count + 1, rows());
+        assertFalse(email().isInvalid());
+        assertFalse(message().isInvalid());
+    }
+
+    @Test
+    void sendResetsFieldsDisablesButtonAndKeepsNewestFirstAcrossVisits() {
+        int count = rows();
+        fillPhoneMessage();
+        click("Send");
+        assertFalse(send().isEnabled());
+        assertTrue(name().isEmpty() && phone().isEmpty() && email().isEmpty() && message().isEmpty());
+        assertTrue(find(Notification.class).exists());
+        assertEquals(count + 1, rows());
+        assertEquals("Ada", first().name());
+        assertEquals("Hello", first().message());
+        test(name()).setValue("Grace");
+        assertTrue(send().isEnabled());
+        test(email()).setValue("grace@example.com");
+        test(message()).setValue("Second message");
+        fireShortcut(Key.ENTER);
+        assertEquals(count + 2, rows());
+        assertEquals("Grace", first().name());
+        assertEquals("Second message", first().message());
+        assertFalse(send().isEnabled());
+        test(find(RouterLink.class).single()).click();
+        assertEquals("About", find(H1.class).single().getText());
+        assertFalse(find(Dialog.class).exists());
+        navigate(ContactView.class);
+        assertEquals(count + 2, rows());
+        assertEquals("Grace", first().name());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void routerLinkCanKeepDraftThenDiscardIt() {
+        fillPhoneMessage();
+        test(find(RouterLink.class).single()).click();
+        assertTrue(find(Dialog.class).single().isOpened());
+        click("Keep editing");
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Ada", name().getValue());
+        assertEquals("12345", phone().getValue());
+        assertEquals("Hello", message().getValue());
+        test(find(RouterLink.class).single()).click();
+        click("Discard");
+        assertEquals("About", find(H1.class).single().getText());
+        navigate(ContactView.class);
+        assertTrue(name().isEmpty());
+    }
+
+    @Test
+    void programmaticNavigationIsGuardedForEachFieldIncludingWhitespace() {
+        for (String label : new String[]{"Name", "Email", "Phone", "Message"}) {
+            if (label.equals("Email")) test(email()).setValue(" ");
+            else if (label.equals("Message")) test(message()).setValue(" ");
+            else test(find(TextField.class).withLabel(label).single()).setValue(" ");
+            UI.getCurrent().navigate(AboutView.class);
+            assertTrue(find(Dialog.class).single().isOpened(), label);
+            click("Discard");
+            assertInstanceOf(AboutView.class, getCurrentView());
+            navigate(ContactView.class);
+        }
+    }
+
+    @Test
+    void everyFieldEditReenablesSend() {
+        for (String label : new String[]{"Name", "Email", "Phone", "Message"}) {
+            fillPhoneMessage();
+            click("Send");
+            assertFalse(send().isEnabled());
+            if (label.equals("Email")) test(email()).setValue("test@example.com");
+            else if (label.equals("Message")) test(message()).setValue("edited");
+            else test(find(TextField.class).withLabel(label).single()).setValue("edited");
+            assertTrue(send().isEnabled(), label);
+            name().clear(); email().clear(); phone().clear(); message().clear();
+        }
+    }
+}
